import { CitationSource } from './CitationSource';
/**
 * The props passed to a custom `bodyTemplate` component for the `Citation` component.
 *
 * When a `bodyTemplate` is provided, it replaces the default rendering of the
 * resource details body (title, description, URL) for each source.
 */
export interface CitationBodyTemplateProps {
    /** The citation sources to render. */
    sources: CitationSource[];
}
